<!--
 * 消息反馈管理页面
 *
 * <p>展示和管理用户对消息的反馈，包含平均评分、反馈总数、正面反馈比例等指标，
 * 以及反馈列表的查看和隐藏操作。
 *
 * @path apps/message-web/src/views/feedback/index.vue
 * @author ydsz-team
 * @since 1.0.0
-->
<script lang="ts" setup>
/**
 * 消息反馈管理（列表页）
 * <p>消费后端契约 MessageFeedbackController（src/api/messageFeedback.ts，auto-generated by bash/gen-contract.py）：
 * pageFeedback() 分页查询反馈列表，getAverageRating() 获取平均评分，
 * shouldReduceFrequency() 判断是否应降频。支持查看详情、隐藏反馈操作。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import { Page } from '@ydsz/common-ui';
import { createLogger } from '@ydsz-core/shared/utils';
import { computed, onMounted, reactive, ref } from 'vue';

import type { MsgFeedbackVO } from '#/api/models';
import { YdBadge, YdButtonBase, YdCard, YdCardContent, YdDialog, YdDialogContent, YdDialogFooter, YdDialogHeader, YdDialogTitle, YdDialogDescription, YdInput, YdSelectBase, YdSelectContentBase, YdSelectItemBase, YdSelectTriggerBase, YdSelectValueBase, YdTable, YdTableColumn, YdEmptyState, YdRate } from '@ydsz-core/ydsz-ui';
import { getAverageRating, pageFeedback } from '#/api/messageFeedback';

defineOptions({ name: 'FeedbackManagement' });

const logger = createLogger('message-feedback');

/** 加载状态 */
const loading = ref(false);

/** 反馈列表数据 */
const feedbackList = ref<MsgFeedbackVO[]>([]);

/** 分页信息 */
const pageInfo = reactive({ page: 1, size: 20, total: 0 });

/** 平均评分指标 */
const averageRating = ref(0);

/** 反馈总数 */
const totalFeedback = ref(0);

/** 正面反馈比例（4-5 分占比） */
const positiveRatio = computed(() => {
  if (feedbackList.value.length === 0) return 0;
  const positiveCount = feedbackList.value.filter(
    (item) => (item.rating ?? 0) >= 4,
  ).length;
  return Math.round((positiveCount / feedbackList.value.length) * 100);
});

/** 查询参数 */
const searchParams = reactive({
  channel: '',
  userId: '',
});

/** 详情弹窗可见性 */
const detailVisible = ref(false);

/** 当前查看详情的反馈 */
const currentDetail = ref<MsgFeedbackVO | null>(null);

/** 评分分布 */
const ratingDistribution = ref<Record<string, number>>({});

/** 状态标签类型 */
function getStatusType(status?: string): 'success' | 'danger' | 'warning' | 'info' {
  const upper = (status ?? '').toUpperCase();
  if (upper === 'PROCESSED') return 'success';
  if (upper === 'PENDING') return 'warning';
  return 'info';
}

/** 状态标签 YdBadge variant 映射 */
function getStatusVariant(status?: string): 'default' | 'destructive' | 'outline' | 'secondary' {
  const type = getStatusType(status);
  if (type === 'danger') return 'destructive';
  if (type === 'warning') return 'outline';
  if (type === 'info') return 'secondary';
  return 'default';
}

/** 状态标签文本 */
function getStatusLabel(status?: string): string {
  const labels: Record<string, string> = {
    PENDING: '待处理',
    PROCESSED: '已处理',
    HIDDEN: '已隐藏',
  };
  return labels[(status ?? '').toUpperCase()] ?? status ?? '-';
}

/** 加载反馈列表 */
async function loadFeedback(): Promise<void> {
  loading.value = true;
  try {
    const res = await pageFeedback({
      page: pageInfo.page,
      size: pageInfo.size,
      channel: searchParams.channel || undefined,
      userId: searchParams.userId || undefined,
    });
    feedbackList.value = res.data ?? [];
    pageInfo.total = res.total ?? 0;
  } catch (error) {
    logger.warn('查询反馈列表失败: {}', error);
    feedbackList.value = [];
    pageInfo.total = 0;
  } finally {
    loading.value = false;
  }
}

/** 加载平均评分指标 */
async function loadAverageRating(): Promise<void> {
  try {
    const ratings = await getAverageRating({
      userId: searchParams.userId || undefined,
      channel: searchParams.channel || undefined,
    });
    ratingDistribution.value = ratings;
    averageRating.value = Number(ratings.average ?? 0);
    totalFeedback.value = Number(ratings.total ?? 0);
  } catch (error) {
    logger.warn('查询平均评分失败: {}', error);
    averageRating.value = 0;
    totalFeedback.value = 0;
  }
}

/** 执行查询 */
function handleSearch(): void {
  pageInfo.page = 1;
  loadFeedback();
  loadAverageRating();
}

/** 查看详情 */
function handleViewDetail(row: MsgFeedbackVO): void {
  currentDetail.value = row;
  detailVisible.value = true;
}

/** 隐藏反馈 */
async function handleHideFeedback(row: MsgFeedbackVO): Promise<void> {
  logger.info('隐藏反馈: id={}', row.id);
  // 契约 API 暂无隐藏接口，预留扩展
  showToast.info('隐藏反馈功能待后端接口支持');
}

/** 重置查询 */
function handleReset(): void {
  searchParams.channel = '';
  searchParams.userId = '';
  handleSearch();
}

onMounted(() => {
  handleSearch();
});
</script>

<template>
  <Page auto-content-height>
    <div class="feedback-container p-4">
      <!-- 顶部指标卡片区 -->
      <div class="mb-4 grid grid-cols-1 gap-4 md:grid-cols-3">
        <YdCard>
          <YdCardContent class="flex flex-col items-center pt-6">
            <span class="text-sm text-muted-foreground">平均评分</span>
            <div class="mt-2 flex items-center gap-2">
              <YdRate :model-value="averageRating" disabled allow-half />
              <span class="text-2xl font-bold text-amber-500">{{ averageRating.toFixed(1) }}</span>
            </div>
          </YdCardContent>
        </YdCard>
        <YdCard>
          <YdCardContent class="flex flex-col items-center pt-6">
            <span class="text-sm text-muted-foreground">反馈总数</span>
            <span class="mt-2 text-2xl font-bold text-blue-600">{{ totalFeedback }}</span>
          </YdCardContent>
        </YdCard>
        <YdCard>
          <YdCardContent class="flex flex-col items-center pt-6">
            <span class="text-sm text-muted-foreground">正面反馈比例</span>
            <span class="mt-2 text-2xl font-bold text-green-600">{{ positiveRatio }}%</span>
          </YdCardContent>
        </YdCard>
      </div>

      <!-- 查询区域 -->
      <YdCard class="mb-4">
        <YdCardContent class="pt-6">
          <div class="flex items-center gap-3">
            <YdInput
              v-model="searchParams.userId"
              placeholder="用户ID"
              class="w-44"
            />
            <YdSelectBase v-model="searchParams.channel">
              <YdSelectTriggerBase class="w-36">
                <YdSelectValueBase placeholder="渠道" />
              </YdSelectTriggerBase>
              <YdSelectContentBase>
                <YdSelectItemBase value="EMAIL">邮件</YdSelectItemBase>
                <YdSelectItemBase value="SMS">短信</YdSelectItemBase>
                <YdSelectItemBase value="INBOX">站内信</YdSelectItemBase>
                <YdSelectItemBase value="WEBHOOK">Webhook</YdSelectItemBase>
              </YdSelectContentBase>
            </YdSelectBase>
            <YdButtonBase @click="handleSearch">查询</YdButtonBase>
            <YdButtonBase variant="outline" @click="handleReset">重置</YdButtonBase>
          </div>
        </YdCardContent>
      </YdCard>

      <!-- 反馈列表 -->
      <YdCard>
        <YdCardContent class="pt-6">
          <YdTable loading="loading" :data="feedbackList" stripe border style="width: 100%">
            <YdTableColumn type="index" label="序号" width="60" align="center" />
            <YdTableColumn prop="userId" label="用户ID" width="140" />
            <YdTableColumn prop="msgId" label="消息ID" width="180" />
            <YdTableColumn label="评分" width="200" align="center">
              <template #default="{ row }">
                <YdRate :model-value="row.rating ?? 0" disabled allow-half />
              </template>
            </YdTableColumn>
            <YdTableColumn prop="content" label="反馈内容" min-width="200" show-overflow-tooltip />
            <YdTableColumn label="反馈类型" width="110" align="center">
              <template #default="{ row }">
                <YdBadge v-if="row.feedbackType" variant="secondary">{{ row.feedbackType }}</YdBadge>
                <span v-else>-</span>
              </template>
            </YdTableColumn>
            <YdTableColumn label="状态" width="100" align="center">
              <template #default="{ row }">
                <YdBadge :variant="getStatusVariant(row.status)">
                  {{ getStatusLabel(row.status) }}
                </YdBadge>
              </template>
            </YdTableColumn>
            <YdTableColumn prop="createdAt" label="创建时间" width="170" />
            <YdTableColumn label="操作" width="160" fixed="right" align="center">
              <template #default="{ row }">
                <YdButtonBase size="sm" variant="link" @click="handleViewDetail(row)">
                  查看详情
                </YdButtonBase>
                <YdButtonBase size="sm" variant="link" class="text-destructive" @click="handleHideFeedback(row)">
                  隐藏
                </YdButtonBase>
              </template>
            </YdTableColumn>
            <template #empty>
              <YdEmptyState description="暂无反馈数据" />
            </template>
          </YdTable>

          <!-- 分页 -->
          <div class="mt-4 flex justify-end">
            <YdButtonBase
              variant="outline"
              :disabled="pageInfo.page <= 1"
              @click="pageInfo.page--; loadFeedback()"
            >
              上一页
            </YdButtonBase>
            <span class="mx-4 self-center text-sm text-muted-foreground">
              第 {{ pageInfo.page }} 页，共 {{ Math.ceil(pageInfo.total / pageInfo.size) || 1 }} 页
            </span>
            <YdButtonBase
              variant="outline"
              :disabled="pageInfo.page * pageInfo.size >= pageInfo.total"
              @click="pageInfo.page++; loadFeedback()"
            >
              下一页
            </YdButtonBase>
          </div>
        </YdCardContent>
      </YdCard>

      <!-- 详情弹窗 -->
      <YdDialog v-model:open="detailVisible">
        <YdDialogContent class="max-w-[520px]">
          <YdDialogHeader>
            <YdDialogTitle>反馈详情</YdDialogTitle>
          </YdDialogHeader>
          <div v-if="currentDetail" class="space-y-3">
            <div class="flex">
              <span class="w-24 text-muted-foreground">用户ID：</span>
              <span>{{ currentDetail.userId ?? '-' }}</span>
            </div>
            <div class="flex">
              <span class="w-24 text-muted-foreground">消息ID：</span>
              <span>{{ currentDetail.msgId ?? '-' }}</span>
            </div>
            <div class="flex items-center">
              <span class="w-24 text-muted-foreground">评分：</span>
              <YdRate :model-value="currentDetail.rating ?? 0" disabled allow-half />
            </div>
            <div class="flex">
              <span class="w-24 text-muted-foreground">反馈类型：</span>
              <span>{{ currentDetail.feedbackType ?? '-' }}</span>
            </div>
            <div class="flex">
              <span class="w-24 text-muted-foreground">状态：</span>
              <YdBadge :variant="getStatusVariant(currentDetail.status)">
                {{ getStatusLabel(currentDetail.status) }}
              </YdBadge>
            </div>
            <div class="flex">
              <span class="w-24 text-muted-foreground">创建时间：</span>
              <span>{{ currentDetail.createdAt ?? '-' }}</span>
            </div>
            <div>
              <span class="text-muted-foreground">反馈内容：</span>
              <p class="mt-1 rounded bg-muted p-3 text-sm">
                {{ currentDetail.content || '无内容' }}
              </p>
            </div>
          </div>
        </YdDialogContent>
      </YdDialog>
    </div>
  </Page>
</template>
